function l(t){return[30,120,300,1800,7200,21600,86400,604800].find(u=>t/u<=366)||Math.ceil(t/366)}function h(t,u){const m=new Map;for(const[a,n,o=n,e=n,f=1]of t){if(!Number.isFinite(a)||!Number.isFinite(n)||!(f>0))continue;const c=Math.floor(a/u)*u,i=m.get(c)||{sum:0,count:0,min:1/0,max:-1/0};i.sum+=n*f,i.count+=f,i.min=Math.min(i.min,o??n),i.max=Math.max(i.max,e??n),m.set(c,i)}const r=[];for(const[a,n]of[...m].sort((o,e)=>o[0]-e[0]))r.length&&a*1e3-r.at(-1)[0]>u*1500&&r.push([a*1e3-u*1e3,null]),r.push([a*1e3,n.sum/n.count,n.min,n.max,n.count]);return r}function x(t){return t<60?`${t}秒`:t<3600?`${t/60}分钟`:t<86400?`${t/3600}小时`:`${Math.round(t/86400)}天`}export{l as a,x as i,h as t};
